// counter.svelte.ts — runes work in plain modules.
// The compiler rewrites $state into the internal signal source,
// so this state is usable from any component (or even from
// another .svelte.ts module).
export let count = $state(0);

export function increment(): void {
  count += 1;
}

export function reset(): void {
  count = 0;
}

